import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.Dsl682W-.js";const m=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"docs/guide/troubleshooting.md","filePath":"guide/troubleshooting.md"}'),i={name:"docs/guide/troubleshooting.md"};function n(d,e,s,l,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Start with the <a href="./../reference/compatibility.html">tested compatibility rows</a> and the <a href="./../reference/actions.html">status action</a>. Diagnose an isolated kitty instance before changing a daily-use configuration.</p><h2 id="symptoms-and-recovery" tabindex="-1">Symptoms and recovery <a class="header-anchor" href="#symptoms-and-recovery" aria-label="Permalink to &quot;Symptoms and recovery&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th><th>Recovery</th></tr></thead><tbody><tr><td>No image change after <code>cd</code></td><td>Is native shell integration reporting a fresh local directory? Is the pane active?</td><td>Verify <a href="./shells.html">shell setup</a> and the rule root. Do not infer shell state from a running program.</td></tr><tr><td>A nested directory gets the parent image</td><td>Does the deeper rule normalize to the directory being visited?</td><td>Check physical paths and remove duplicate roots; <a href="./configuration.html#reload-safely">reload valid rules</a>.</td></tr><tr><td>The image works only from one directory</td><td>Is the image path relative to the JSON file, and does that file exist?</td><td>Put the image at the configured local path or correct the path.</td></tr><tr><td>Reload reports invalid configuration</td><td>Unknown field, duplicate root, schema version, malformed JSON, or wrong value type.</td><td>Fix the named validation problem. The last valid configuration remains active.</td></tr><tr><td>Image cannot be read</td><td>File access, PNG validity, dimensions, size, or a vanished file.</td><td>Use a readable PNG within the <a href="./../reference/configuration.html#images">limits</a>. Avoid changing global permissions.</td></tr><tr><td>Image changes in the wrong window</td><td>Active-pane targeting or stale event handling has failed.</td><td>Pause the affected instance and report a sanitized reproduction. This is not expected supported behavior.</td></tr><tr><td>The original image does not return</td><td>Baseline profile or ownership cannot be established.</td><td>Stop automatic updates and inspect <a href="./kitty-settings.html#restoring-the-baseline">restoration limits</a>. Do not clear a valid original image.</td></tr><tr><td>Status says <code>baseline-unknown</code> after manual setup</td><td>The OS window existed before the watcher loaded, or an external writer’s exact image is unknown.</td><td>Follow the <a href="./installation.html#existing-windows">existing-windows requirement</a>. Resume cannot reconstruct unknown image state.</td></tr><tr><td>A fallback displays but an image error remains</td><td>A matching rule’s image failed even though the fallback is usable.</td><td>Fix the rule image and reload. A normal unmatched-directory fallback has no image-error reason.</td></tr><tr><td>Switching pauses after another tool runs</td><td>Another background writer may have taken ownership.</td><td>Choose one owner and follow the documented explicit resume workflow.</td></tr><tr><td>A remote or multiplexer directory is ignored</td><td>That context is not qualified for automatic reporting.</td><td>Use a normal kitty background in that context.</td></tr><tr><td>Setup finds an existing owned-name file</td><td>A user file or previous installation conflicts.</td><td>Keep the file. Review preview/rollback information before any replacement.</td></tr><tr><td>Status says <code>filesystem-timeout</code></td><td>A local filesystem operation did not finish within five seconds.</td><td>Restore normal access to the file or directory, then issue a new event or reload. Queued work stays bounded and no idle collector continues.</td></tr><tr><td>Pause reports <code>restore-failed</code></td><td>The original image could not be applied.</td><td>Keep the installation intact, fix the cause, and retry restore before removal. Ownership remains held so recovery is possible.</td></tr></tbody></table><h2 id="useful-diagnostic-details" tabindex="-1">Useful diagnostic details <a class="header-anchor" href="#useful-diagnostic-details" aria-label="Permalink to &quot;Useful diagnostic details&quot;">​</a></h2><p>Record the Kittyscape artifact identity, kitty version, shell/version, OS/architecture/display backend, configuration profile, and the shortest sequence that reproduces the problem. Include whether focus, a theme reload, or another writer ran before the failure.</p><p>Default diagnostics omit directory names, usernames, image paths, and command lines. Additional test or kitty logs can disclose local paths; inspect them before sharing. Use neutral example paths such as <code>/example/Project One</code>, and remove credentials and unrelated command history.</p><h2 id="keep-a-usable-terminal" tabindex="-1">Keep a usable terminal <a class="header-anchor" href="#keep-a-usable-terminal" aria-label="Permalink to &quot;Keep a usable terminal&quot;">​</a></h2><p>Rule and image failures appear in status while the shell remains usable. If a failure interrupts the prompt, pause/restore, then use <a href="./uninstall.html">removal and rollback</a>. Do not enable unrestricted remote control or install unrelated software as a troubleshooting shortcut.</p>',9)])])}const p=t(i,[["render",n]]);export{m as __pageData,p as default};
